/* Token Radar — dark dashboard. No network, no framework. */
:root {
  --bg: #0a1120;
  --panel: #101c30;
  --panel-2: #152640;
  --line: #22385a;
  --text: #e8eef7;
  --muted: #93a5bd;
  --accent: #2dd4bf;
  --accent-2: #f5b94a;
  --pos: #34d399;
  --neg: #f87171;
  --radius: 12px;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.skip { position: absolute; left: -999px; top: 0; background: var(--accent); color: #04211d; padding: 8px 14px; border-radius: 0 0 8px 0; }
.skip:focus { left: 0; }
.shell { max-width: 1180px; margin: 0 auto; padding: 20px 20px 48px; }
.top { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 20px; letter-spacing: .2px; }
.mark { width: 16px; height: 16px; border-radius: 50%; background: radial-gradient(circle at 35% 35%, var(--accent), #0d9488 70%); display: inline-block; }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.top-meta span { background: var(--panel); border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px; font-size: 13px; color: var(--muted); }
.lede { margin: 22px 0 16px; }
.lede h1 { font-size: 30px; line-height: 1.2; margin: 0 0 8px; }
.lede p { color: var(--muted); margin: 0; max-width: 760px; }
.facts { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px 14px; }
.fact span { display: block; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.fact b { font-size: 22px; }
.controls { display: flex; gap: 12px; align-items: end; flex-wrap: wrap; margin: 18px 0 12px; }
.field label, .field .sub { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; }
.field input[type="search"], .field select {
  background: var(--panel); color: var(--text); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 10px; font: inherit; min-width: 200px;
}
.field input[type="search"] { min-width: 260px; }
.check { display: flex; align-items: center; gap: 6px; padding-bottom: 8px; color: var(--muted); font-size: 14px; }
.tabs { display: flex; gap: 6px; }
.tabs button, .button {
  background: var(--panel); color: var(--text); border: 1px solid var(--line);
  border-radius: 8px; padding: 8px 14px; font: inherit; cursor: pointer;
}
.tabs button[aria-pressed="true"], .button.primary { background: var(--accent); color: #04211d; border-color: var(--accent); font-weight: 700; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; padding-bottom: 8px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: 12px 16px; color: var(--muted); font-size: 13px; }
th, td { padding: 10px 12px; text-align: left; border-top: 1px solid var(--line); white-space: nowrap; }
thead th { border-top: 0; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .05em; }
th button { background: none; border: 0; color: inherit; font: inherit; cursor: pointer; padding: 0; }
tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr[data-selected="true"] { background: var(--panel-2); }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.name b { display: block; }
.badge-new { background: #3a2f10; color: var(--accent-2); border-radius: 999px; padding: 1px 8px; font-size: 11px; font-weight: 700; margin-left: 6px; vertical-align: middle; letter-spacing: .04em; }
.name .sub, .sub { color: var(--muted); font-size: 13px; }
.pos { color: var(--pos); }
.neg { color: var(--neg); }
.implied { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
.bar { width: 72px; height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--accent); }
.status { background: #123f36; color: var(--accent); border-radius: 999px; padding: 2px 10px; font-size: 12px; }
.status.live { background: #3a2f10; color: var(--accent-2); }
.empty { padding: 32px; text-align: center; }
.empty h2 { margin: 0 0 6px; }
.empty p { color: var(--muted); }
.model { padding: 18px 20px; margin-top: 16px; }
.model h2 { margin: 0 0 6px; font-size: 19px; }
.model p { color: var(--muted); }
.formula {
  background: var(--bg); border: 1px solid var(--line); border-radius: 8px;
  padding: 12px 14px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px; overflow-x: auto; margin: 10px 0;
}
.mult-table { width: 100%; font-size: 13px; margin-top: 8px; }
.mult-table th, .mult-table td { padding: 6px 8px; }
.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 16px; max-width: 720px; width: calc(100% - 32px); padding: 0; }
.detail::backdrop { background: rgba(3, 7, 18, .7); }
.detail-head { display: flex; justify-content: space-between; gap: 16px; padding: 20px 22px 0; }
.detail-head h2 { margin: 4px 0; font-size: 24px; }
.close { background: var(--panel-2); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 6px 12px; cursor: pointer; height: fit-content; }
.detail-section { padding: 16px 22px 22px; border-top: 1px solid var(--line); margin-top: 16px; }
.detail-section h3 { margin: 0 0 10px; font-size: 16px; }
.equation { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 20px; }
.equation > div { display: flex; justify-content: space-between; border-bottom: 1px dashed var(--line); padding: 6px 0; }
.equation span { color: var(--muted); }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin-bottom: 12px; }
.steps .cost { display: block; color: var(--muted); font-size: 13px; margin-top: 2px; }
.comps { width: 100%; font-size: 13px; }
.comps th, .comps td { padding: 6px 8px; }
@media (max-width: 760px) {
  .facts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .lede h1 { font-size: 24px; }
  .equation { grid-template-columns: 1fr; }
  .field input[type="search"] { min-width: 0; width: 100%; }
}
